import { httpPost } from "./lib/http.js";

export interface Parcel {
  id: string;
  trackingNumber: string;
  weightGrams: number;
  status: string;
  createdAt: string;
}

export function notifyShop(webhookUrl: string, parcel: Parcel): Promise<void> {
  return httpPost<void>(webhookUrl, parcel);
}
